/**
 * fix (2026-04-27): コミュニティサブメニュー新規作成 ページ版
 *
 * ルート: /community/:id/sub/:subType/create
 *
 * subType:
 *   - 'recruitment' : 募集 (PoC 完了)
 *   - 'event' / 'thread' / 'appeal' / 'news' : 後続段階で同様に拡張
 *
 * 各 *-create コンポーネントを @Optional() MatDialogRef で改修済の場合、
 * Input に communityId を渡してそのまま再利用できる。
 */
import { Component, ChangeDetectionStrategy, OnInit } from '@angular/core';
import { CommonModule, Location } from '@angular/common';
import { ActivatedRoute, Router } from '@angular/router';
import { MatIconModule } from '@angular/material/icon';
import { RecruitmentCreateComponent } from '../../components/recruitment-create/recruitment-create.component';
import { EventCreateComponent } from '../../components/event-create/event-create.component';
import { ThreadCreateComponent } from '../../components/thread-create/thread-create.component';
import { AppealCreateComponent } from '../../components/appeal-create/appeal-create.component';

type SubType = 'recruitment' | 'event' | 'thread' | 'appeal' | 'news';

const SUB_TYPE_LABELS: Record<SubType, string> = {
  recruitment: '募集を作成',
  event: 'イベントを作成',
  thread: 'スレッドを作成',
  appeal: 'アピールを作成',
  news: 'ニュースを作成',
};

@Component({
  selector: 'app-community-sub-create-page',
  standalone: true,
  imports: [CommonModule, MatIconModule, RecruitmentCreateComponent, EventCreateComponent, ThreadCreateComponent, AppealCreateComponent],
  templateUrl: './community-sub-create-page.component.html',
  styleUrls: ['./community-sub-create-page.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CommunitySubCreatePageComponent implements OnInit {
  communityId = '';
  subType: SubType = 'recruitment';
  title = '';
  /** ページ版が完成しているサブ種別 (recruitment / event / thread / appeal) */
  supportedSubTypes: Set<SubType> = new Set(['recruitment', 'event', 'thread', 'appeal']);

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private location: Location,
  ) {}

  ngOnInit(): void {
    this.communityId = this.route.snapshot.paramMap.get('id') || '';
    const sub = (this.route.snapshot.paramMap.get('subType') || 'recruitment') as SubType;
    this.subType = sub;
    this.title = SUB_TYPE_LABELS[sub] || 'コンテンツを作成';
  }

  onBack(): void {
    if (window.history.length > 1) {
      this.location.back();
    } else {
      this.router.navigate(['/community', this.communityId]);
    }
  }

  isSupported(): boolean {
    return this.supportedSubTypes.has(this.subType);
  }
}
